ALTER FUNCTION [dbo].[GetAssetKeyHashById]( @id bigint ) RETURNS TABLE AS RETURN (
select A.AssetTypeID, A.ID, CONVERT( varchar(32), SUBSTRING(HASHBYTES('SHA1', STRING_AGG(cast(FieldTypeID as nvarchar) + ':' + Value, char(59))), 3, 32), 2) as KeyHash from Asset A inner join Field F on F.ObjectType = A.Object and F.ObjectID = A.ObjectID inner join FieldType FT on FT.ID = F.FieldTypeID and FT.AssetTypeID = A.AssetTypeID and FT.IsPartOfKey = 1 where a.id = @id group by A.AssetTypeID, A.ID
)
